{
  "schema_version": 1,
  "name": "cand_bet",
  "summary": "Listener 10-point probability allocation (betting) across referents.",
  "charter": {
    "question": "How do people distribute graded belief across candidate referents when interpreting referring expressions and prior expectations?"
  },
  "instructions": {
    "welcome": "Welcome to our study on how people understand descriptions of objects.",
    "task": "In each round, you will see a row of objects that differ in their parts. A speaker sees the same objects and wants to point out one of them. On most rounds, the speaker says a single word that is true of the object they mean. On some rounds, you have not heard the speaker's word yet. Your task is to split 10 points across the objects to show how likely you think each object is to be the one the speaker meant. Give more points to objects you think are more likely, and 0 points to objects you think cannot be the one.",
    "comprehension_checks": [
      {
        "question": "How do you answer on each round?",
        "options": [
          "Split 10 points across the objects according to how likely each one is to be the speaker's target.",
          "Click every object that has the named part.",
          "Type a new word for the speaker."
        ],
        "correct": 0
      }

